contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5_000);

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        assert(
            c.initialized()
            && c.baseToken() == _baseToken
            && c.nft() == _nft
            && c.virtualBaseTokenReserves() == _virtualBaseTokenReserves
            && c.virtualNftReserves() == _virtualNftReserves
            && c.changeFee() == _changeFee
            && c.feeRate() == _feeRate
            && c.merkleRoot() == _merkleRoot
            && c.useStolenNftOracle() == _useStolenNftOracle
            && c.payRoyalties() == _payRoyalties
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofArr,
        bool[] calldata flagsArr
    ) external payable {
        C.MerkleMultiProof calldata proof;
        proof.proof = proofArr;
        proof.flags = flagsArr;

        bool reverted;
        try c.buy(tokenIds, tokenWeights, proof) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 vnr = c.virtualNftReserves();

        assert(reverted || vnr != 0);
    }

    receive() external payable {}
}

