contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights) external view {
        require(tokenIds.length > 0);
        require(tokenIds.length == tokenWeights.length);

        // Fresh pool: merkleRoot is bytes32(0), so no proof is needed and weights are ignored.
        C.MerkleMultiProof memory proof;
        uint256 sum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        assert(sum == tokenIds.length * 1e18);
    }
}

