contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 inputAmount) public {
        require(inputAmount <= 2**96);
        require(c.virtualNftReserves() <= type(uint256).max - inputAmount);
        uint256 vb = c.virtualBaseTokenReserves();
        require(vb <= 2**128);
        uint256 vn = c.virtualNftReserves();
        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);
        uint256 grossOutput = inputAmount * vb / (vn + inputAmount);
        uint256 rate = c.feeRate();
        assert(
            netOutputAmount + feeAmount + protocolFeeAmount == grossOutput &&
            feeAmount == grossOutput * rate / 10_000 &&
            netOutputAmount <= grossOutput
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 inputAmount) public {
        require(inputAmount > 0 && inputAmount <= 2**64);
        uint256 vb = c.virtualBaseTokenReserves();
        uint256 vn = c.virtualNftReserves();
        require(vn + inputAmount >= vn);
        (uint256 net, uint256 fee, uint256 pf) = c.sellQuote(inputAmount);
        assert(net + fee + pf == inputAmount * vb / (vn + inputAmount));
    }
}

