contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights) external {
        require(tokenIds.length == tokenWeights.length);
        require(c.merkleRoot() == bytes32(0));
        bytes32[] memory proof = new bytes32[](1);
        proof[0] = keccak256("x");
        bool[] memory flags = new bool[](1);
        flags[0] = true;
        C.MerkleMultiProof memory mp = C.MerkleMultiProof({proof: proof, flags: flags});
        uint256 sum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp);
        assert(sum == tokenIds.length * 1e18 && c.merkleRoot() == bytes32(0));
    }
}

